data class Noqte(val x: Int, val y: Int) {

    operator fun plus(digeri: Noqte) = Noqte(x + digeri.x, y + digeri.y)
    operator fun minus(digeri: Noqte) = Noqte(x - digeri.x, y - digeri.y)
    operator fun times(k: Int) = Noqte(x * k, y * k)

    // оператор in
    operator fun contains(deyer: Int) = deyer == x || deyer == y

    // индексация: p[0], p[1]
    operator fun get(index: Int) = when (index) {
        0 -> x
        1 -> y
        else -> throw IndexOutOfBoundsException()
    }
}

fun main() {
    val a = Noqte(1, 2)
    val b = Noqte(3, 4)

    println(a + b)
    println(b - a)
    println(Noqte(2, 3) * 3)
    println(2 in a)          // вызывается contains()
    println("x = ${a[0]}")   // вызывается get()
}

