fun main() {
    // 1) Простое сопоставление значения
    val x = 2
    when (x) {
        1 -> println("Bir")
        2, 3 -> println("Kiçik rəqəm: $x")   // несколько значений через запятую
        else -> println("Digər")
    }

    // 2) Как выражение + диапазон
    val gun = 3
    val tip = when (gun) {
        in 1..5 -> "İş günü"
        6, 7 -> "İstirahət"
        else -> "Yanlış gün"
    }
    println(tip)

    // 3) Проверка типа (is) — работает smart cast
    val obyekt: Any = 42
    when (obyekt) {
        is Int -> println("Rəqəm")
        is String -> println("Uzunluq: ${obyekt.length}")  // автоматически String
        is List<*> -> println("Siyahı, ${obyekt.size} element")
        else -> println("Naməlum tip")
    }

    // 4) when без аргумента — заменяет цепочку if-else
    val temperatur = 5
    val geyim = when {
        temperatur < 0 -> "Qalın palto"
        temperatur in 1..10 -> "1-dən 10-a qədər"
        temperatur in 11..20 -> "Yüngül gödəkçə"
        else -> "Köynək"
    }
    println(geyim)

    // 5) Возврат результата when напрямую
    println(olcuAdi(150))
}

fun olcuAdi(sm: Int): String = when {
    sm < 100 -> "Kiçik"
    sm < 180 -> "Böyük"
    else -> "Nəhəng"
}

