fun main() {
    // break — полностью останавливает цикл
    for (i in 1..5) {
        if (i == 3) break
        print("$i ")
    }
    println()

    // continue — пропускает текущий шаг
    for (i in 1..5) {
        if (i % 2 == 0) continue
        print("$i ")
    }
    println()

    // Метка — чтобы выйти из вложенных циклов
    xarici@ for (i in 1..3) {
        for (j in 1..3) {
            if (i * j == 2) {
                println("Tapıldı: ($i, $j)")
                break@xarici     // выходит из обоих циклов
            }
        }
    }
}

